            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">THE FIRST FREE DAY</text><text x=\"550\" y=\"100\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\">A paraphrase of Chapter 8</text><rect x=\"100\" y=\"200\" width=\"900\" height=\"300\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"550\" y=\"280\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"24\">We have no brothers now,</text><text x=\"550\" y=\"330\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"24\">and the day belongs to us alone --</text><text x=\"550\" y=\"380\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"24\">our body, our hunger, our hands</text><text x=\"550\" y=\"430\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"24\">are our own.</text><text x=\"550\" y=\"600\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-size=\"20\">Adapted from Anthem, Chapter 8</text><text x=\"550\" y=\"650\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Note: he still says we -- the word I is not his yet</text></svg>",
            "caption": "Freedom arrives before the vocabulary for it"
