            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"150\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"215\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">THE HOUSE</text><text x=\"550\" y=\"265\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Dormitory-raised eyes</text><text x=\"550\" y=\"305\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">What would puzzle them most?</text><rect x=\"300\" y=\"450\" width=\"220\" height=\"140\" rx=\"15\" fill=\"rgba(236,72,153,0.1)\" stroke=\"#ec4899\" stroke-width=\"2\"/><text x=\"410\" y=\"530\" text-anchor=\"middle\" fill=\"#ec4899\" font-size=\"22\">BED</text><rect x=\"580\" y=\"450\" width=\"220\" height=\"140\" rx=\"15\" fill=\"rgba(236,72,153,0.1)\" stroke=\"#ec4899\" stroke-width=\"2\"/><text x=\"690\" y=\"530\" text-anchor=\"middle\" fill=\"#ec4899\" font-size=\"22\">BED</text></svg>",
            "caption": "Count the beds"
